(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-026":{scenario:{company:"Lumora Travel Booking",supervisor:{name:"Phan Gia Bảo",role:{vi:"Trưởng nhóm Kỹ thuật Giao diện",en:"Frontend Tech Lead"}},ref_code:"FE-1907",title:{vi:"Bản mới đến tay người dùng. Không trang trắng.",en:"Ship the new build. No blank pages."},brief:{vi:"Sau khi phát hành v5 của trang đặt phòng, nhiều người dùng gặp trang trắng và lỗi ChunkLoadError: trình duyệt vẫn giữ index.html cũ trỏ tới các tệp JS đã bị xóa. Các tệp JS, CSS trong thư mục assets đều có mã băm nội dung trong tên tệp. Chính sách lưu đệm đã duyệt: HTML luôn kiểm tra lại với máy chủ, tệp có mã băm lưu đệm 365 ngày. Đối chiếu cấu hình nháp FE-1907, sửa header Cache-Control của index.html và giá trị max-age của tệp có mã băm, rồi lập báo cáo có căn cứ.",en:"After release v5 of the booking site, many users see a blank page and ChunkLoadError: browsers keep an old index.html pointing to deleted JS files. JS and CSS files in the assets folder carry a content hash in their names. The approved caching policy: HTML is always revalidated with the server, hashed files are cached for 365 days. Compare draft config FE-1907, correct the Cache-Control header of index.html and the max-age of hashed files, then write an evidence-based report."},reference_title:{vi:"Chính sách lưu đệm đã duyệt · FE-1907",en:"Approved caching policy · FE-1907"},fields:[{id:"HTML_CACHE",label:{vi:"Cache-Control của index.html",en:"Cache-Control for index.html"},initial:"max-age=31536000",expected:"no-cache",choices:["max-age=31536000","no-cache","no-store"],reference:"Quy tắc lưu đệm HTML",ref_value:{vi:"HTML được lưu đệm nhưng phải kiểm tra lại với máy chủ trước mỗi lần dùng",en:"HTML may be stored but must be revalidated with the server before every use"},hint:{vi:"Phân biệt chỉ thị cấm lưu hoàn toàn với chỉ thị cho lưu nhưng bắt buộc kiểm tra lại.",en:"Tell apart the directive that forbids storage from the one that stores but forces revalidation."}},{id:"ASSET_MAXAGE",label:{vi:"max-age cho tệp có mã băm (giây)",en:"max-age for hashed files (seconds)"},initial:"86400",expected:"31536000",reference:"Quy tắc lưu đệm tệp tĩnh",ref_value:{vi:"Tệp tĩnh có mã băm nội dung: lưu đệm 365 ngày, kèm immutable",en:"Static files with a content hash: cache for 365 days, with immutable"},hint:{vi:"max-age tính bằng giây; quy đổi đúng số ngày trong chính sách.",en:"max-age is in seconds; convert the policy's number of days correctly."}}],sop32:{vi:"max-age (giây) = số ngày x 24 x 3600. Tệp có mã băm đổi tên khi nội dung đổi nên được lưu dài hạn; index.html không có mã băm nên phải kiểm tra lại mỗi lần để nhận bản phát hành mới.",en:"max-age (seconds) = days x 24 x 3600. Hashed files get a new name when content changes, so they are cached long-term; index.html has no hash and must be revalidated every time to pick up new releases."},context:{label:"CDN CONFIG / FE-1907",metrics:[{label:{vi:"Phiên bản phát hành",en:"Release"},value:"v5"},{label:{vi:"Lưu đệm tệp có mã băm",en:"Hashed file cache"},value:"365 days"},{label:{vi:"Lỗi ghi nhận 1 giờ",en:"Errors in 1 hour"},value:"2140 ChunkLoadError"}]},crisis:{vi:"Trưởng nhóm marketing nhắn: “Em chèn giúp đoạn mã theo dõi của bên thứ ba ghi lại toàn bộ thao tác gõ phím ở form đặt phòng, kể cả số hộ chiếu, và ẩn nút Từ chối cookie để tỷ lệ đồng ý cao hơn. Chiều nay chạy chiến dịch rồi.”",en:"The marketing lead writes: “Please add a third-party tracking script that records every keystroke on the booking form, passport numbers included, and hide the Reject cookies button so consent goes up. The campaign starts this afternoon.”"},options:{safe:{vi:"Từ chối ghi dữ liệu nhạy cảm và ẩn nút từ chối; báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đề xuất đo lường dựa trên đồng ý, che các trường nhạy cảm và chỉ thu sự kiện cần thiết.",en:"Refuse to capture sensitive data or hide the reject button; inform the lead and the data protection team, and propose consent-based analytics that masks sensitive fields and collects only needed events."},shortcut:{vi:"Chèn mã theo dõi và ẩn nút từ chối trong lúc chạy chiến dịch, sau đó gỡ ra.",en:"Add the script and hide the reject button during the campaign, removing them later."},wait:{vi:"Không trả lời và để marketing tự nhờ người khác chèn mã.",en:"Ignore the message and let marketing ask someone else to add the script."}},questions:{vi:["Vì sao bạn chọn header đó cho index.html và giá trị max-age đó cho tệp có mã băm? Dẫn chính sách FE-1907 và kết quả kiểm tra header.","Bạn bảo vệ dữ liệu cá nhân của khách đặt phòng và vẫn hỗ trợ marketing đo hiệu quả chiến dịch như thế nào?"],en:["Why did you choose that header for index.html and that max-age for hashed files? Cite policy FE-1907 and the header checks.","How do you protect guests' personal data while still helping marketing measure the campaign?"]},hints:{vi:["Kiểm tra header thực tế của index.html và so với quy tắc HTML trong chính sách đã duyệt.","Theo SOP mục 3.2, đổi 365 ngày ra giây trước khi nhập giá trị max-age.","Đọc lại SOP mục 4.2: thu thập dữ liệu cá nhân phải có căn cứ, có đồng ý hợp lệ và không dùng giao diện đánh lừa."],en:["Check the real index.html header and compare it with the HTML rule in the approved policy.","Per SOP 3.2, convert 365 days to seconds before entering the max-age value.","Re-read SOP 4.2: personal data collection needs a legal basis and valid consent, with no deceptive interface."]},terminal:{system:"web-build-sim",settable:["HTML_CACHE","ASSET_MAXAGE"],commands:[{cmd:"curl -i /index.html",out:{vi:"HTTP/2 200 | cache-control: max-age=31536000 | age: 604800 | tham chiếu app.3f9c1a.js (đã bị xóa ở v5)",en:"HTTP/2 200 | cache-control: max-age=31536000 | age: 604800 | references app.3f9c1a.js (deleted in v5)"}},{cmd:"ls dist/assets",out:{vi:"app.8d27e4.js  vendor.b10c55.js  app.41aa09.css: tên tệp có mã băm nội dung",en:"app.8d27e4.js  vendor.b10c55.js  app.41aa09.css: file names carry a content hash"}},{cmd:"curl -i /assets/app.8d27e4.js",out:{vi:"HTTP/2 200 | cache-control: public, max-age=86400 | tải lại sau mỗi ngày dù nội dung không đổi",en:"HTTP/2 200 | cache-control: public, max-age=86400 | refetched daily although content never changes"}},{cmd:"cat errors.log",out:{vi:"ChunkLoadError: Loading chunk 412 failed (app.3f9c1a.js 404) x 2140 trong 1 giờ qua",en:"ChunkLoadError: Loading chunk 412 failed (app.3f9c1a.js 404) x 2140 in the last hour"}}]}},learning:{summary:{vi:"Lập trình viên giao diện web xây dựng phần người dùng nhìn thấy và tương tác: trang, thành phần, biểu mẫu, trạng thái ứng dụng, gọi API và tối ưu hiệu năng tải trang. Họ làm việc với React, Next.js hoặc Vue, bảo đảm khả năng truy cập theo WCAG, Core Web Vitals đạt chuẩn, bảo mật phía trình duyệt và tôn trọng quyền riêng tư của người dùng.",en:"A frontend developer builds what users see and interact with: pages, components, forms, application state, API calls and load performance. Working with React, Next.js or Vue, the developer ensures WCAG accessibility, healthy Core Web Vitals, browser-side security and respect for user privacy."},responsibilities:{vi:["Chuyển thiết kế thành thành phần giao diện tái sử dụng, đáp ứng mọi kích thước màn hình.","Kết nối API, quản lý trạng thái, xử lý lỗi và trạng thái tải dữ liệu rõ ràng.","Tối ưu hiệu năng: chia nhỏ gói mã, lưu đệm, tối ưu hình ảnh và chỉ số Core Web Vitals.","Bảo đảm khả năng truy cập, đa ngôn ngữ và tương thích trình duyệt.","Viết kiểm thử thành phần, kiểm thử đầu cuối và tham gia rà soát mã."],en:["Turn designs into reusable, responsive UI components for every screen size.","Connect APIs, manage state and handle errors and loading states clearly.","Optimize performance: code splitting, caching, image optimization and Core Web Vitals.","Ensure accessibility, internationalization and browser compatibility.","Write component and end-to-end tests and take part in code reviews."]},competencies:[{name:{vi:"HTML, CSS & JavaScript",en:"HTML, CSS & JavaScript"},desc:{vi:"Viết HTML ngữ nghĩa, CSS bố cục linh hoạt và JavaScript hiện đại, rõ ràng.",en:"Write semantic HTML, flexible CSS layouts and clear modern JavaScript."}},{name:{vi:"Framework thành phần",en:"Component frameworks"},desc:{vi:"Dùng React, Next.js hoặc Vue: vòng đời, quản lý trạng thái, SSR, SSG và định tuyến.",en:"Use React, Next.js or Vue: lifecycle, state management, SSR, SSG and routing."}},{name:{vi:"Hiệu năng web",en:"Web performance"},desc:{vi:"Đo và cải thiện LCP, INP, CLS bằng lưu đệm HTTP, chia gói và tối ưu tài nguyên.",en:"Measure and improve LCP, INP and CLS with HTTP caching, bundle splitting and asset optimization."}},{name:{vi:"Khả năng truy cập",en:"Accessibility"},desc:{vi:"Áp dụng WCAG: tương phản, bàn phím, nhãn biểu mẫu và thuộc tính ARIA đúng chỗ.",en:"Apply WCAG: contrast, keyboard access, form labels and ARIA used correctly."}},{name:{vi:"Bảo mật & quyền riêng tư",en:"Security & privacy"},desc:{vi:"Phòng XSS, áp dụng CSP, quản lý mã bên thứ ba và đồng ý cookie hợp lệ.",en:"Prevent XSS, apply CSP, control third-party scripts and handle cookie consent properly."}}],knowledge:{vi:["Chuẩn HTML và DOM, mô hình sự kiện, vòng lặp sự kiện của JavaScript.","WCAG 2.2 mức AA, ví dụ văn bản thường cần độ tương phản tối thiểu 4,5:1.","Core Web Vitals mức tốt: LCP tối đa 2,5 giây, INP tối đa 200 ms, CLS tối đa 0,1.","Lưu đệm HTTP theo RFC 9111: max-age, no-cache, no-store, immutable và kiểm tra lại bằng ETag.","Phòng chống XSS theo khuyến nghị OWASP và chính sách bảo mật nội dung (CSP).","Quy định hiện hành của Việt Nam về bảo vệ dữ liệu cá nhân và sự đồng ý của người dùng."],en:["HTML and DOM standards, the event model and the JavaScript event loop.","WCAG 2.2 level AA, for example a minimum 4.5:1 contrast ratio for normal text.","Good Core Web Vitals: LCP up to 2.5 s, INP up to 200 ms, CLS up to 0.1.","HTTP caching per RFC 9111: max-age, no-cache, no-store, immutable and ETag revalidation.","XSS prevention per OWASP guidance and Content Security Policy (CSP).","Current Vietnamese rules on personal data protection and user consent."]},tools:["React / Next.js / Vue","TypeScript","Vite / webpack","DevTools trình duyệt","Lighthouse","Playwright"],kpis:{vi:["Tỷ lệ lượt truy cập đạt Core Web Vitals mức tốt.","Số lỗi JavaScript phía người dùng trên 1000 phiên.","Điểm kiểm tra khả năng truy cập và số lỗi WCAG còn mở.","Tỷ lệ chuyển đổi của luồng đặt phòng sau mỗi bản phát hành."],en:["Share of visits with good Core Web Vitals.","Client-side JavaScript errors per 1000 sessions.","Accessibility audit score and open WCAG issues.","Booking funnel conversion after each release."]},day:[{time:"08:30",vi:"Xem bảng lỗi phía người dùng và chỉ số hiệu năng thực tế của ngày hôm qua.",en:"Review client error dashboards and yesterday's real-user performance."},{time:"09:30",vi:"Họp nhanh với nhóm, nhận thẻ việc làm biểu mẫu thanh toán mới.",en:"Stand-up with the team and pick up the new checkout form task."},{time:"11:00",vi:"Dựng thành phần theo thiết kế, kiểm tra bàn phím và trình đọc màn hình.",en:"Build components from the design and test keyboard and screen reader use."},{time:"14:00",vi:"Tối ưu ảnh lớn ở đầu trang và cấu hình lưu đệm trên CDN.",en:"Optimize the hero image and configure CDN caching."},{time:"16:00",vi:"Viết kiểm thử đầu cuối, mở yêu cầu hợp nhất mã và rà soát mã cho đồng nghiệp.",en:"Write end-to-end tests, open a merge request and review a teammate's code."}],mistakes:{vi:["Lưu đệm index.html quá lâu nên người dùng kẹt ở bản cũ và gặp lỗi tải chunk sau khi phát hành.","Gắn loading=lazy cho ảnh lớn đầu trang, làm chậm chỉ số LCP.","Chèn mã bên thứ ba thu dữ liệu nhạy cảm hoặc dùng giao diện đánh lừa để lấy đồng ý."],en:["Caching index.html too long so users stay on the old build and hit chunk load errors.","Putting loading=lazy on the hero image, which slows LCP.","Adding third-party scripts that collect sensitive data or using dark patterns to win consent."]},career:[{vi:"Lập trình viên giao diện thực tập / mới vào nghề",en:"Junior frontend developer"},{vi:"Lập trình viên giao diện web",en:"Frontend developer"},{vi:"Lập trình viên giao diện cao cấp / Trưởng nhóm kỹ thuật",en:"Senior frontend developer / Tech lead"},{vi:"Kiến trúc sư giao diện / Quản lý kỹ thuật",en:"Frontend architect / Engineering manager"}],glossary:[{term:"Cache-Control",vi:"Header HTTP quy định trình duyệt và CDN được lưu đệm phản hồi bao lâu và như thế nào.",en:"HTTP header that tells browsers and CDNs how and how long to cache a response."},{term:"Content hash",vi:"Mã băm nội dung gắn vào tên tệp, đổi khi nội dung đổi, cho phép lưu đệm dài hạn an toàn.",en:"Hash of the file content in its name; it changes with the content, allowing safe long-term caching."},{term:"LCP",vi:"Largest Contentful Paint: thời điểm phần tử nội dung lớn nhất trong khung nhìn hiển thị xong.",en:"Largest Contentful Paint: when the largest content element in the viewport finishes rendering."},{term:"SSR",vi:"Kết xuất phía máy chủ: tạo HTML trên máy chủ cho mỗi yêu cầu để tải nhanh và tốt cho SEO.",en:"Server-side rendering: generating HTML on the server per request for faster loads and better SEO."},{term:"CSP",vi:"Chính sách bảo mật nội dung giới hạn nguồn được phép tải script, style, hình ảnh.",en:"Content Security Policy limiting where scripts, styles and images may load from."}],quiz:[{q:{vi:"max-age cho tệp lưu đệm 30 ngày là bao nhiêu giây?",en:"What max-age in seconds caches a file for 30 days?"},options:{vi:["86400","604800","2592000","31536000"],en:["86400","604800","2592000","31536000"]},answer:2,explain:{vi:"30 x 24 x 3600 = 2592000 giây.",en:"30 x 24 x 3600 = 2592000 seconds."}},{q:{vi:"Chỉ thị nào cho phép lưu bản sao nhưng buộc kiểm tra lại với máy chủ trước mỗi lần dùng?",en:"Which directive allows storing a copy but forces revalidation with the server before each use?"},options:{vi:["no-store","no-cache","immutable","max-age=31536000"],en:["no-store","no-cache","immutable","max-age=31536000"]},answer:1,explain:{vi:"no-cache vẫn cho lưu nhưng phải kiểm tra lại; no-store cấm lưu hoàn toàn.",en:"no-cache stores but must revalidate; no-store forbids storing entirely."}},{q:{vi:"Theo Core Web Vitals, ngưỡng LCP mức tốt là bao nhiêu?",en:"Under Core Web Vitals, what is the good threshold for LCP?"},options:{vi:["Tối đa 2,5 giây","Tối đa 4 giây","Tối đa 200 ms","Tối đa 0,1"],en:["Up to 2.5 s","Up to 4 s","Up to 200 ms","Up to 0.1"]},answer:0,explain:{vi:"LCP tốt là tối đa 2,5 giây; 200 ms là ngưỡng INP, 0,1 là ngưỡng CLS.",en:"Good LCP is up to 2.5 s; 200 ms is the INP threshold and 0.1 is the CLS threshold."}},{q:{vi:"Marketing yêu cầu ẩn nút Từ chối cookie và ghi lại mọi phím gõ trong form, kể cả số hộ chiếu. Bạn làm gì?",en:"Marketing asks you to hide the Reject cookies button and record every keystroke on the form, passport numbers included. What do you do?"},options:{vi:["Làm theo trong thời gian chiến dịch","Chỉ ẩn nút, không ghi phím gõ","Làm và không báo ai","Từ chối, báo bộ phận bảo vệ dữ liệu và đề xuất đo lường dựa trên đồng ý"],en:["Comply for the campaign period","Hide the button but skip keystrokes","Do it and tell no one","Refuse, inform data protection and propose consent-based measurement"]},answer:3,explain:{vi:"Thu dữ liệu nhạy cảm không cần thiết và đánh lừa người dùng để lấy đồng ý vi phạm nguyên tắc bảo vệ dữ liệu cá nhân.",en:"Collecting unnecessary sensitive data and tricking users into consent breaches personal data protection principles."}}],tools_en:["React / Next.js / Vue","TypeScript","Vite / webpack","Browser DevTools","Lighthouse","Playwright"]}}})})(window.KKR);
